{
 "requirements": [
  {
   "id": "R1",
   "text": "Extract headlines and links from three news sites."
  },
  {
   "id": "R2",
   "text": "Respect robots.txt and wait 2 seconds between requests per site."
  },
  {
   "id": "R3",
   "text": "Store results in SQLite without duplicates across runs."
  },
  {
   "id": "R4",
   "text": "--since option prints headlines collected after a date."
  },
  {
   "id": "R5",
   "text": "Retry failed requests up to 3 times with exponential backoff."
  },
  {
   "id": "R6",
   "text": "Log errors instead of crashing."
  }
 ],
 "constraints": [
  "requests + BeautifulSoup only",
  "Python 3.10+"
 ],
 "deliverables": [
  "code",
  "requirements.txt",
  "README"
 ]
}

